import com.google.android.gms.tasks.Task;
import com.google.android.gms.tasks.OnSuccessListener;
import com.google.android.gms.tasks.OnFailureListener;
import com.google.android.gms.integrity.IntegrityManager;
import com.google.android.gms.integrity.IntegrityManagerFactory;
import com.google.android.gms.integrity.IntegrityTokenRequest;
import com.google.android.gms.integrity.IntegrityTokenResponse;
import android.util.Base64;
import android.util.Log;

public void requestAndVerifyIntegrityToken() {
    String nonce = Base64.encodeToString("this_is_my_nonce".getBytes(), Base64.URL_SAFE | Base64.NO_WRAP | Base64.NO_PADDING);

    IntegrityManager integrityManager = IntegrityManagerFactory.create(getApplicationContext());
    Task<IntegrityTokenResponse> integrityTokenResponseTask = integrityManager
            .requestIntegrityToken(IntegrityTokenRequest.builder().setNonce(nonce).build());

    integrityTokenResponseTask.addOnSuccessListener(new OnSuccessListener<IntegrityTokenResponse>() {
        @Override
        public void onSuccess(IntegrityTokenResponse response) {
            String token = response.token();
            // Decode JWT
            String[] parts = token.split("\\.");
            String payload = new String(Base64.decode(parts[1], Base64.URL_SAFE));
            Log.d("IntegrityToken", "Decoded Payload: " + payload);
        }
    });

    integrityTokenResponseTask.addOnFailureListener(new OnFailureListener() {
        @Override
        public void onFailure(Exception e) {
            Log.e("IntegrityToken", "Token request failed", e);
        }
    });
}
