import java.awt.Graphics2D;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import com.google.zxing.BarcodeFormat;
import com.google.zxing.EncodeHintType;
import com.google.zxing.MultiFormatWriter;
import com.google.zxing.client.j2se.MatrixToImageWriter;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel;

public class Create_QR {
    public static void main(String[] args) {
        try {
            String qrCodeData = "This is the text";
            String filePath = "C:\\Users\\Nirmalw\\Desktop\\Projects\\QR\\test\\test_img\\my_QR_with_text.png";
            String charset = "UTF-8"; 

            Map<EncodeHintType, ErrorCorrectionLevel> hintMap = new HashMap<>();
            hintMap.put(EncodeHintType.ERROR_CORRECTION, ErrorCorrectionLevel.L);

            BitMatrix matrix = new MultiFormatWriter().encode(new String(qrCodeData.getBytes(charset), charset),
                    BarcodeFormat.QR_CODE, 500, 500, hintMap);

            BufferedImage qrImage = MatrixToImageWriter.toBufferedImage(matrix);

            // Add text to the image
            Graphics2D g = qrImage.createGraphics();
            g.setFont(new Font("Arial", Font.BOLD, 20));
            g.drawString("User: John Doe", 20, 530); // Add user name
            g.drawString("Event: My Event", 20, 560); // Add event name
            g.dispose();

            // Save the image with text
            ImageIO.write(qrImage, "PNG", new File(filePath));

            System.out.println("QR Code with text created successfully!");
        } catch (Exception e) {
            System.err.println(e);
        }
    }
}
