@Configuration
public class LocaleConfig implements WebMvcConfigurer {
    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new LocaleInterceptor()).addPathPatterns("/**");
    }

    public class LocaleInterceptor implements HandlerInterceptor {
        private final Set<String> allowedLocales = new HashSet<>(Arrays.asList("en", "hi"));

        @Override
        public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
            String localeParam = request.getParameter("locale");
            if (localeParam != null && !allowedLocales.contains(localeParam)) {
                throw new IllegalArgumentException("Invalid locale: " + localeParam);
            }
            return true;
        }
    }
}
