@ApiBaseSiteIdAndUserIdParam
public TestListWsDTO getTest(
        @RequestParam(required = false, defaultValue = DEFAULT_FIELD_SET) final String fields) {
    Authentication authentication = SecurityContextHolder.getContext().getAuthentication();

    if (authentication == null || authentication.getPrincipal() instanceof User == false) {
        throw new AccessDeniedException("User is not authenticated");
    }

    String userId = authentication.getName();  // Get the username (userId) from the authentication

    // Fetch the customer based on userId
    CustomerModel customer = customerFacade.getCustomerForUid(userId);

    if (customer == null) {
        throw new AccessDeniedException("Customer not found for userId: " + userId);
    }

    if (userFacade.isAnonymousUser()) {
        throw new AccessDeniedException("Anonymous user is not allowed");
    }

    // Proceed with the business logic
    final CustomerData customerData = customerFacade.getCurrentCustomer();
    // Additional logic for the customer data processing
    return new TestListWsDTO();
}
