import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlElementWrapper;

import java.util.List;

@JacksonXmlRootElement(localName = "Item")
public class Item {

    @JacksonXmlProperty(localName = "SNO")
    private String sNo;

    @JacksonXmlProperty(localName = "Weight")
    private Float weight;

    @JacksonXmlProperty(localName = "A")
    @JacksonXmlElementWrapper(useWrapping = false)
    private List<String> aList;

    @JacksonXmlProperty(localName = "B")
    @JacksonXmlElementWrapper(useWrapping = false)
    private List<String> bList;

    // Custom serializer to serialize A and B tags as pairs
    public static class CustomSerializer extends com.fasterxml.jackson.databind.JsonSerializer<Item> {
        @Override
        public void serialize(Item item, com.fasterxml.jackson.core.JsonGenerator gen, 
                              com.fasterxml.jackson.databind.SerializerProvider serializers) 
                throws IOException, JsonProcessingException {
            gen.writeStartObject();
            gen.writeStringField("SNO", item.sNo);
            gen.writeStringField("Weight", item.weight.toString());

            List<String> aList = item.aList;
            List<String> bList = item.bList;

            for (int i = 0; i < Math.min(aList.size(), bList.size()); i++) {
                gen.writeStringField("A", aList.get(i));
                gen.writeStringField("B", bList.get(i));
            }

            gen.writeEndObject();
        }
    }

    @JsonSerialize(using = CustomSerializer.class)
    public Item(String sNo, Float weight, List<String> aList, List<String> bList) {
        this.sNo = sNo;
        this.weight = weight;
        this.aList = aList;
        this.bList = bList;
    }

    // Getters and Setters
    public String getsNo() {
        return sNo;
    }

    public void setsNo(String sNo) {
        this.sNo = sNo;
    }

    public Float getWeight() {
        return weight;
    }

    public void setWeight(Float weight) {
        this.weight = weight;
    }

    public List<String> getaList() {
        return aList;
    }

    public void setaList(List<String> aList) {
        this.aList = aList;
    }

    public List<String> getbList() {
        return bList;
    }

    public void setbList(List<String> bList) {
        this.bList = bList;
    }
}
