import javafx.application.Application;
import javafx.beans.value.ChangeListener;
import javafx.beans.value.ObservableValue;
import javafx.scene.Scene;
import javafx.scene.control.Spinner;
import javafx.scene.control.SpinnerValueFactory;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

public class SpinnerExample extends Application {

    @Override
    public void start(Stage primaryStage) {
        Spinner<Integer> spinnerMin = new Spinner<>();
        Spinner<Integer> spinnerMax = new Spinner<>();

        spinnerMin.setValueFactory(new SpinnerValueFactory.IntegerSpinnerValueFactory(2, 6, 2));
        spinnerMax.setValueFactory(new SpinnerValueFactory.IntegerSpinnerValueFactory(2, 6, 6));

        spinnerMin.valueProperty().addListener((observable, oldValue, newValue) -> {
            spinnerMax.setValueFactory(new SpinnerValueFactory.IntegerSpinnerValueFactory(newValue, 6, spinnerMax.getValue()));
            if (newValue.equals(spinnerMax.getValue())) {
                spinnerMin.getEditor().setStyle("-fx-opacity: 0.5;");
                spinnerMax.getEditor().setStyle("-fx-opacity: 0.5;");
            } else {
                spinnerMin.getEditor().setStyle("");
                spinnerMax.getEditor().setStyle("");
            }
        });

        spinnerMax.valueProperty().addListener((observable, oldValue, newValue) -> {
            spinnerMin.setValueFactory(new SpinnerValueFactory.IntegerSpinnerValueFactory(2, newValue, spinnerMin.getValue()));
            if (newValue.equals(spinnerMin.getValue())) {
                spinnerMin.getEditor().setStyle("-fx-opacity: 0.5;");
                spinnerMax.getEditor().setStyle("-fx-opacity: 0.5;");
            } else {
                spinnerMin.getEditor().setStyle("");
                spinnerMax.getEditor().setStyle("");
            }
        });

        VBox vbox = new VBox(spinnerMin, spinnerMax);
        Scene scene = new Scene(vbox, 300, 200);
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
