private void loadAd(int triggerClicks) {
    AdRequest adRequest = new AdRequest.Builder().build();
    InterstitialAd.load(this, (triggerClicks == triggerClicksNav) 
        ? "ca-app-pub-3940256099942544/1033173712" 
        : "ca-app-pub-3940256099942544/8691691433", adRequest, 
        new InterstitialAdLoadCallback() {
            @Override
