import org.xhtmlrenderer.pdf.ITextRenderer;
import com.lowagie.text.DocumentException;
import java.io.*;

public class HtmlToPdfConverter {

    public static void convertHtmlToPdf(String htmlString, String outputPath) throws IOException, DocumentException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        OutputStream outputStream = new FileOutputStream(outputPath);

        ITextRenderer renderer = new ITextRenderer();
        renderer.setDocumentFromString(htmlString);

        // Set the font for rendering Cyrillic characters
        renderer.getFontResolver().addFont("path/to/your/font.ttf", true); // Provide a valid font path
        renderer.layout();
        renderer.createPDF(outputStream);

        byteArrayOutputStream.writeTo(outputStream);
        outputStream.close();
    }

    public static void main(String[] args) throws IOException, DocumentException {
        String htmlString = "<!DOCTYPE html>\n" +
                "<html lang=\"ru\">\n" +
                "<head>\n" +
                "    <meta charset=\"UTF-8\"/>\n" +
                "    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"/>\n" +
                "    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n" +
                "</head>\n" +
                "<body>\n" +
                "    <h3>?????? ???</h3>\n" +
                "</body>\n" +
                "</html>";

        String path = "A.pdf";
        convertHtmlToPdf(htmlString, path);
    }
}
