import java.io.File;
import java.lang.management.ManagementFactory;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class FileDescriptorChecker {

    public static List<String> findProcessesHoldingFile(String filePath) {
        List<String> result = new ArrayList<>();
        String pid = getCurrentPid();

        try {
            Process process = Runtime.getRuntime().exec("cmd.exe /c handle.exe -accepteula " + filePath);
            process.waitFor();
            String output = new String(process.getInputStream().readAllBytes());
            String[] lines = output.split("\n");

            for (String line : lines) {
                if (line.contains(filePath)) {
                    result.add(line);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return result;
    }

    private static String getCurrentPid() {
        String name = ManagementFactory.getRuntimeMXBean().getName();
        return name.split("@")[0];
    }

    public static void main(String[] args) {
        String filePath = "C:\\path\\to\\your\\file.txt";
        List<String> processes = findProcessesHoldingFile(filePath);

        for (String process : processes) {
            System.out.println(process);
        }
    }
}
