                "    </SOAP-ENV:Body>\n" +
                "</SOAP-ENV:Envelope>\n";

        InputStream input = new ByteArrayInputStream(strSource.getBytes("UTF-8"));
        TransformerFactory transformerFactory = TransformerFactory.newInstance();
        StreamSource xsltStream = new StreamSource(xsltfile);
