        baseUrlConnection.setRequestProperty("Accept-Language", "en-US,en;q=0.9");

        if (cookie == null) {
            List<String> cookies = baseUrlConnection.getHeaderFields().get("Set-Cookie");
            cookie = cookies.get(0).split(";", 2)[0]; // Store the cookie
        }

        URL url = new URL("https://www.nseindia.com/api/option-chain-indices?symbol=MIDCPNIFTY");
        HttpURLConnection httpURLConnection = (HttpURLConnection) url.openConnection();
        httpURLConnection.setRequestMethod("GET");
        httpURLConnection.addRequestProperty("Cookie", cookie); // Use the stored cookie
        httpURLConnection.setRequestProperty("Connection", "keep-alive");
        httpURLConnection.setRequestProperty("Cache-Control", "max-age=0");
        httpURLConnection.setRequestProperty("Upgrade-Insecure-Requests", "1");
        httpURLConnection.setRequestProperty("User-Agent", "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/89.0.4389.114 Safari/537.36");
