public String fetchMavenPage(String address) throws IOException {
    System.setProperty("https.proxyHost", "xxxx");
    System.setProperty("https.proxyPort", "xxxx");

    URL url = new URL(address);
    HttpsURLConnection con = (HttpsURLConnection) url.openConnection();
    con.setRequestMethod("GET");
    con.setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/110.0.0.0 Safari/537.36");
    con.setRequestProperty("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8");
    con.setRequestProperty("Referer", "https://mvnrepository.com/");
    con.setRequestProperty("Connection", "keep-alive");

    try (BufferedReader br = new BufferedReader(new InputStreamReader(
            con.getResponseCode() < 300 ? con.getInputStream() : con.getErrorStream(), StandardCharsets.UTF_8))) {
        return br.lines().collect(Collectors.joining());
    }
}
