            return path;
        }
    }

    @Override
    public void start(Stage primaryStage) {
        TableView<FilePath> tableView = new TableView<>();

        TableColumn<FilePath, String> pathColumn = new TableColumn<>("Path");
        pathColumn.setCellValueFactory(new PropertyValueFactory<>("path"));
        pathColumn.setPrefWidth(200);

        pathColumn.setCellFactory(column -> new TableCell<>() {
            private final Text text = new Text();

            @Override
            protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) {
                    setGraphic(null);
                } else {
                    String truncated = truncatePath(item, (int) getTableColumn().getWidth());
                    text.setText(truncated);
                    text.setStyle("-fx-text-alignment: right;");
                    setGraphic(text);
                }
            }
        });

        tableView.widthProperty().addListener((obs, oldWidth, newWidth) -> tableView.refresh());

        tableView.getColumns().add(pathColumn);
        tableView.getItems().addAll(
            new FilePath("/usr/local/bin/someverylongdirectoryname/file.txt"),
            new FilePath("/usr/local/bin/someverylongdirectoryname/file2.txt")
        );

        primaryStage.setScene(new Scene(tableView, 300, 200));
        primaryStage.show();
    }

    private String truncatePath(String path, int maxWidth) {
        final int maxChars = maxWidth / 7;
        if (path.length() <= maxChars) return path;
        return ".." + path.substring(path.length() - (maxChars - 2));
    }

    public static void main(String[] args) {
        launch(args);
    }
}
