import pandas as pd
import numpy as np

def safe_series(values, dtype):
    arr = np.array(values, dtype=dtype)
    if (arr > np.iinfo(dtype).max).any() or (arr < np.iinfo(dtype).min).any():
        raise OverflowError("Value exceeds dtype limits")
    return pd.Series(arr, dtype=dtype)
