from typing import Callable, Dict
from functools import wraps

def remember(f: Callable[[int], int]) -> Callable[[int], int]:
    class Wrapper:
        memory: Dict[int, int]

        def __init__(self, f: Callable[[int], int]):
            self.f = f
            self.memory = {}

        def __call__(self, n: int) -> int:
            if n not in self.memory:
                self.memory[n] = self.f(n)
            return self.memory[n]

    @wraps(f)
    def wrapper(n: int) -> int:
        return wrapper._wrapper(n)

    wrapper._wrapper = Wrapper(f)
    return wrapper

@remember
def fib(n: int) -> int:
    if n < 2:
        return 1
    return fib(n - 2) + fib(n - 1)
,"[""from typing import Callable, Dict\r\nfrom functools import wraps\r\n\r\ndef remember(f: Callable[[int], int]) -> Callable[[int], int]:\r\n    class Wrapper:\r\n        memory: Dict[int, int]\r\n\r\n        def __init__(self, f: Callable[[int], int]):\r\n            self.f = f\r\n            self.memory = {}\r\n\r\n        def __call__(self, n: int) -> int:\r\n            if n not in self.memory:\r\n                self.memory[n] = self.f(n)\r\n            return self.memory[n]\r\n\r\n    @wraps(f)\r\n    def wrapper(n: int) -> int:\r\n        return wrapper._wrapper(n)\r\n\r\n    wrapper._wrapper = Wrapper(f)\r\n    return wrapper\r\n\r\n@remember\r\ndef fib(n: int) -> int:\r\n    if n < 2:\r\n        return 1\r\n    return fib(n - 2) + fib(n - 1)\r\n""]",0

