def fizz_buzz(arr, i):
    if (three := i % 3 == 0) and (five := i % 5 == 0):
        arr.append("FizzBuzz")
    elif three:
        arr.append("Fizz")
    elif five:
        arr.append("Buzz")
    else:
        arr.append(str(i-1))
