import polars as pl
import numpy as np
import functools

def combine_series(pls):
    return functools.reduce(lambda a, b: a.join(b, on='index', how='full', coalesce=True), pls).sort(by='index')

N, C = 300000, 20
pls = []
for i in range(C):
    A = pl.DataFrame({
        "index": np.linspace(i, N*3-i, num=N, dtype=np.int32),
        f"A{i}": np.arange(N, dtype=np.float32),
    })
    pls.append(A)

result = combine_series(pls)
