class BST:
    def __init__(self, val):
        self.value = val
        self.left = None
        self.right = None

    def add_child(self, val):
        if self.value:
            if val < self.value:
                if self.left == None:
                    self.left = BST(val)
                else:
                    self.left.add_child(val)
            else:
                if val > self.value:
                    if self.right == None:
                        self.right = BST(val)
                    else:
                        self.right.add_child(val)
        else:
            self.value = val

    def traverse_pre(self, values=None):
        if values is None:
            values = []
        values.append(self.value)

        if self.left:
            self.left.traverse_pre(values)

        if self.right:
            self.right.traverse_pre(values)

        return values


Tree = BST(5)
