        if (node.isArray()) {
            ArrayNode array = node.deepCopy();
            array.forEach(u ->
                    u.fields().forEachRemaining(o -> {
                        if (!o.getValue().isContainerNode())
                            flat.put(o.getKey(), o.getValue());
                        else {
                            parser(o.getValue(), flat);
                        }
                    }));
        } else {
            node.fields().forEachRemaining(o -> flat.put(o.getKey(), o.getValue()));
        }
