                .setAutoCancel(true)
                .setStyle(new NotificationCompat.BigTextStyle().bigText(text))
                .setDefaults(NotificationCompat.DEFAULT_ALL);


        NotificationManagerCompat notificationManagerCompat = NotificationManagerCompat.from(context);
