from typing import Sequence


def my_roll(in_column: str | pl.Expr, window: Sequence):
    if isinstance(in_column, str):
        in_column = pl.col(in_column)
    pl_window = range(-window[0], -window[1] - 1, -1)
    return pl.concat_list(in_column.shift(x) for x in pl_window).list.drop_nulls()

def my_roll(in_column: str | pl.Expr, window):
    if isinstance(in_column, str):
        in_column = pl.col(in_column)
    period = f"{window[1]-window[0]+1}i"
    offset = f"{window[0]-1}i"
    return in_column.map_batches(
        lambda s: (
            s.to_frame()
            .with_row_index()
            .select(
                pl.col(s.name).rolling(
                    index_column="index", 
                    period=period, 
                    offset=offset
                )
            )
            .get_column(s.name)
        )
    ),"[""(\r\n    df\r\n    .with_columns(\r\n        y=pl.concat_list(\r\n            pl.col('x').shift(x) \r\n            for x in range(2,-2,-1)\r\n            )\r\n        .list.drop_nulls()\r\n        )\r\n)\r\nshape: (4, 2)\r\nÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂ¬Ã¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂ\r\nÃ¢ÂÂ x   Ã¢ÂÂ y                 Ã¢ÂÂ\r\nÃ¢ÂÂ --- Ã¢ÂÂ ---               Ã¢ÂÂ\r\nÃ¢ÂÂ f64 Ã¢ÂÂ list[f64]         Ã¢ÂÂ\r\nÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂªÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂ¡\r\nÃ¢ÂÂ 1.2 Ã¢ÂÂ [1.2, 1.3]        Ã¢ÂÂ\r\nÃ¢ÂÂ 1.3 Ã¢ÂÂ [1.2, 1.3, 3.4]   Ã¢ÂÂ\r\nÃ¢ÂÂ 3.4 Ã¢ÂÂ [1.2, 1.3, Ã¢ÂÂ¦ 3.5] Ã¢ÂÂ\r\nÃ¢ÂÂ 3.5 Ã¢ÂÂ [1.3, 3.4, 3.5]   Ã¢ÂÂ\r\nÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂ´Ã¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂ\r\n\r\nfrom typing import Sequence\r\n\r\n\r\ndef my_roll(in_column: str | pl.Expr, window: Sequence):\r\n    if isinstance(in_column, str):\r\n        in_column = pl.col(in_column)\r\n    pl_window = range(-window[0], -window[1] - 1, -1)\r\n    return pl.concat_list(in_column.shift(x) for x in pl_window).list.drop_nulls()\r\n\r\ndef my_roll(in_column: str | pl.Expr, window):\r\n    if isinstance(in_column, str):\r\n        in_column = pl.col(in_column)\r\n    period = f""{window[1]-window[0]+1}i""\r\n    offset = f""{window[0]-1}i""\r\n    return in_column.map_batches(\r\n        lambda s: (\r\n            s.to_frame()\r\n            .with_row_index()\r\n            .select(\r\n                pl.col(s.name).rolling(\r\n                    index_column=""index"", \r\n                    period=period, \r\n                    offset=offset\r\n                )\r\n            )\r\n            .get_column(s.name)\r\n        )\r\n   